package chainmap

import "errors"

// Sentinel errors returned (wrapped) by chain operations.
var (
	// ErrNotFound indicates that a requested key or path segment is absent.
	ErrNotFound = errors.New("chainmap: key not found")
	// ErrIndexOutOfRange indicates that a slice index is out of bounds.
	ErrIndexOutOfRange = errors.New("chainmap: index out of range")
	// ErrTypeMismatch indicates that a value had an unexpected concrete type.
	ErrTypeMismatch = errors.New("chainmap: type mismatch")
)

// Package chainmap provides a fluent, chainable API for reading and
// mutating arbitrary map[string]interface{} data.
//
// A Map or Value records the first error encountered along a chain instead
// of panicking, so long chains can be written naturally and inspected once
// at the end:
//
//	name := chainmap.New(data).Path("user.profile.name").StringOr("anonymous")
//	if err := chainmap.New(data).Path("user.id").Err(); err != nil {
//		// handle
//	}
package chainmap

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

// Map is a fluent wrapper around a map[string]interface{}. Accessor and
// mutator methods return a wrapper so calls can be chained. The first error
// encountered is recorded and surfaced by Err; subsequent operations become
// no-ops.
type Map struct {
	data map[string]interface{}
	err  error
}

// New returns a Map that wraps data. A nil map is replaced with an empty
// map so the result is always safe to mutate. The map is used directly, not
// copied; use Clone if the caller needs to retain ownership.
func New(data map[string]interface{}) *Map {
	if data == nil {
		data = make(map[string]interface{})
	}
	return &Map{data: data}
}

// ParseJSON decodes JSON into a Map. The top-level JSON value must be an
// object.
func ParseJSON(data []byte) (*Map, error) {
	var m map[string]interface{}
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("chainmap: parse json: %w", err)
	}
	return New(m), nil
}

// Raw returns the underlying map. Mutating it mutates the Map.
func (m *Map) Raw() map[string]interface{} {
	if m == nil {
		return nil
	}
	return m.data
}

// Err returns the first error recorded during the chain, if any.
func (m *Map) Err() error {
	if m == nil {
		return nil
	}
	return m.err
}

// Len returns the number of keys in the map.
func (m *Map) Len() int {
	if m == nil || m.data == nil {
		return 0
	}
	return len(m.data)
}

// IsEmpty reports whether the map has no keys.
func (m *Map) IsEmpty() bool { return m.Len() == 0 }

// Has reports whether key exists, regardless of its value.
func (m *Map) Has(key string) bool {
	if m == nil || m.data == nil {
		return false
	}
	_, ok := m.data[key]
	return ok
}

// Get returns the value stored at key. A missing key records ErrNotFound.
func (m *Map) Get(key string) *Value {
	if m == nil {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, key))
	}
	if m.err != nil {
		return errValue(m.err)
	}
	v, ok := m.data[key]
	if !ok {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, key))
	}
	return newValue(v)
}

// Path resolves a dot-separated path, descending through nested maps and,
// for numeric segments, slices. See Value.Path for details.
func (m *Map) Path(path string) *Value {
	if m == nil {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, path))
	}
	if m.err != nil {
		return errValue(m.err)
	}
	return newValue(m.data).Path(path)
}

// Set stores value at key and returns the receiver for chaining. Passing a
// *Map, *Slice, or *Value stores its underlying data.
func (m *Map) Set(key string, value interface{}) *Map {
	if m == nil || m.err != nil {
		return m
	}
	m.data[key] = unwrap(value)
	return m
}

// SetPath stores value at a dot-separated path, creating intermediate maps
// as needed. It records ErrTypeMismatch if an intermediate value exists but
// is not a map.
func (m *Map) SetPath(path string, value interface{}) *Map {
	if m == nil || m.err != nil {
		return m
	}
	parts := splitPath(path)
	if len(parts) == 0 {
		m.err = fmt.Errorf("chainmap: empty path")
		return m
	}
	cur := m.data
	for _, part := range parts[:len(parts)-1] {
		next, ok := cur[part]
		if !ok {
			child := make(map[string]interface{})
			cur[part] = child
			cur = child
			continue
		}
		child, ok := next.(map[string]interface{})
		if !ok {
			m.err = fmt.Errorf("%w at %q: expected map, got %T", ErrTypeMismatch, part, next)
			return m
		}
		cur = child
	}
	cur[parts[len(parts)-1]] = unwrap(value)
	return m
}

// Delete removes key from the map and returns the receiver for chaining.
// Deleting a missing key is a no-op.
func (m *Map) Delete(key string) *Map {
	if m == nil || m.err != nil {
		return m
	}
	delete(m.data, key)
	return m
}

// DeletePath removes the value at a dot-separated path. Missing intermediate
// keys are treated as a no-op.
func (m *Map) DeletePath(path string) *Map {
	if m == nil || m.err != nil {
		return m
	}
	parts := splitPath(path)
	if len(parts) == 0 {
		return m
	}
	cur := m.data
	for _, part := range parts[:len(parts)-1] {
		child, ok := cur[part].(map[string]interface{})
		if !ok {
			return m
		}
		cur = child
	}
	delete(cur, parts[len(parts)-1])
	return m
}

// Keys returns the map's keys in sorted order.
func (m *Map) Keys() []string {
	if m == nil || m.data == nil {
		return nil
	}
	keys := make([]string, 0, len(m.data))
	for k := range m.data {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// Values returns the map's values in key-sorted order.
func (m *Map) Values() []*Value {
	if m == nil || m.data == nil {
		return nil
	}
	keys := m.Keys()
	out := make([]*Value, 0, len(keys))
	for _, k := range keys {
		out = append(out, newValue(m.data[k]))
	}
	return out
}

// Each calls fn for every key in sorted order. Returning false stops the
// iteration early. It returns the receiver for chaining.
func (m *Map) Each(fn func(key string, v *Value) bool) *Map {
	if m == nil || m.err != nil {
		return m
	}
	for _, k := range m.Keys() {
		if !fn(k, newValue(m.data[k])) {
			break
		}
	}
	return m
}

// Transform replaces every value with the result of fn, returning the
// receiver for chaining.
func (m *Map) Transform(fn func(key string, v *Value) interface{}) *Map {
	if m == nil || m.err != nil {
		return m
	}
	for k, v := range m.data {
		m.data[k] = unwrap(fn(k, newValue(v)))
	}
	return m
}

// Filter returns a new Map containing only the entries for which fn reports
// true. The receiver is left unchanged.
func (m *Map) Filter(fn func(key string, v *Value) bool) *Map {
	out := New(nil)
	if m == nil || m.err != nil {
		return out
	}
	for k, v := range m.data {
		if fn(k, newValue(v)) {
			out.data[k] = v
		}
	}
	return out
}

// Merge copies the top-level entries of each other map into the receiver,
// overwriting existing keys. Nil maps and maps carrying errors are skipped.
// It returns the receiver for chaining.
func (m *Map) Merge(others ...*Map) *Map {
	if m == nil || m.err != nil {
		return m
	}
	for _, o := range others {
		if o == nil || o.err != nil {
			continue
		}
		for k, v := range o.data {
			m.data[k] = v
		}
	}
	return m
}

// Clone returns a deep copy of the map. Nested maps and slices are copied
// recursively; other values are shared.
func (m *Map) Clone() *Map {
	if m == nil {
		return New(nil)
	}
	out := New(nil)
	if m.err != nil {
		out.err = m.err
		return out
	}
	for k, v := range m.data {
		out.data[k] = deepCopy(v)
	}
	return out
}

func splitPath(path string) []string {
	raw := strings.Split(path, ".")
	parts := make([]string, 0, len(raw))
	for _, p := range raw {
		if p != "" {
			parts = append(parts, p)
		}
	}
	return parts
}

package chainmap

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"
)

// Value is a fluent wrapper around an arbitrary interface{} value pulled
// from a Map or Slice. Like Map, it records the first error encountered and
// exposes it through Err.
type Value struct {
	val interface{}
	err error
}

func newValue(val interface{}) *Value { return &Value{val: val} }

func errValue(err error) *Value { return &Value{err: err} }

// Err returns the first error recorded while producing or reading the value.
func (v *Value) Err() error {
	if v == nil {
		return nil
	}
	return v.err
}

// Interface returns the underlying value.
func (v *Value) Interface() interface{} {
	if v == nil {
		return nil
	}
	return v.val
}

// Raw is an alias for Interface.
func (v *Value) Raw() interface{} { return v.Interface() }

// Exists reports whether the value was found without error.
func (v *Value) Exists() bool { return v != nil && v.err == nil }

// IsNil reports whether the value exists and is nil.
func (v *Value) IsNil() bool { return v.Exists() && v.val == nil }

// String returns the underlying string. It records ErrTypeMismatch if the
// value is not a string. Missing values yield the empty string.
func (v *Value) String() string {
	if v == nil || v.err != nil {
		return ""
	}
	switch x := v.val.(type) {
	case string:
		return x
	case nil:
		return ""
	default:
		v.err = fmt.Errorf("%w: expected string, got %T", ErrTypeMismatch, v.val)
		return ""
	}
}

// StringOr returns the underlying string or def when the value is missing
// or not a string. It never records an error.
func (v *Value) StringOr(def string) string {
	if v == nil || v.err != nil {
		return def
	}
	if s, ok := v.val.(string); ok {
		return s
	}
	return def
}

// Int returns the underlying value as an int. Numeric strings and JSON
// numbers are accepted. It records ErrTypeMismatch on failure.
func (v *Value) Int() int { return int(v.Int64()) }

// IntOr returns the underlying value as an int or def on failure.
func (v *Value) IntOr(def int) int {
	if v == nil || v.err != nil {
		return def
	}
	n, ok := toInt64(v.val)
	if !ok || n > math.MaxInt || n < math.MinInt {
		return def
	}
	return int(n)
}

// Int64 returns the underlying value as an int64. Numeric strings and JSON
// numbers are accepted. It records ErrTypeMismatch on failure.
func (v *Value) Int64() int64 {
	if v == nil || v.err != nil {
		return 0
	}
	n, ok := toInt64(v.val)
	if !ok {
		v.err = fmt.Errorf("%w: expected integer, got %T", ErrTypeMismatch, v.val)
		return 0
	}
	return n
}

// Int64Or returns the underlying value as an int64 or def on failure.
func (v *Value) Int64Or(def int64) int64 {
	if v == nil || v.err != nil {
		return def
	}
	n, ok := toInt64(v.val)
	if !ok {
		return def
	}
	return n
}

// Float64 returns the underlying value as a float64. Numeric strings and
// JSON numbers are accepted. It records ErrTypeMismatch on failure.
func (v *Value) Float64() float64 {
	if v == nil || v.err != nil {
		return 0
	}
	f, ok := toFloat64(v.val)
	if !ok {
		v.err = fmt.Errorf("%w: expected number, got %T", ErrTypeMismatch, v.val)
		return 0
	}
	return f
}

// Float64Or returns the underlying value as a float64 or def on failure.
func (v *Value) Float64Or(def float64) float64 {
	if v == nil || v.err != nil {
		return def
	}
	f, ok := toFloat64(v.val)
	if !ok {
		return def
	}
	return f
}

// Bool returns the underlying bool. Strings are parsed with
// strconv.ParseBool. It records ErrTypeMismatch on failure.
func (v *Value) Bool() bool {
	if v == nil || v.err != nil {
		return false
	}
	b, ok := toBool(v.val)
	if !ok {
		v.err = fmt.Errorf("%w: expected bool, got %T", ErrTypeMismatch, v.val)
		return false
	}
	return b
}

// BoolOr returns the underlying bool or def on failure.
func (v *Value) BoolOr(def bool) bool {
	if v == nil || v.err != nil {
		return def
	}
	b, ok := toBool(v.val)
	if !ok {
		return def
	}
	return b
}

// Get returns the value stored under key when the receiver wraps a map. It
// records ErrTypeMismatch for non-map values and ErrNotFound for missing
// keys.
func (v *Value) Get(key string) *Value {
	if v == nil {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, key))
	}
	if v.err != nil {
		return errValue(v.err)
	}
	m, ok := v.val.(map[string]interface{})
	if !ok {
		return errValue(fmt.Errorf("%w: expected map, got %T", ErrTypeMismatch, v.val))
	}
	val, ok := m[key]
	if !ok {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, key))
	}
	return newValue(val)
}

// Index returns the element at i when the receiver wraps a slice. It records
// ErrTypeMismatch for non-slices and ErrIndexOutOfRange for invalid indexes.
func (v *Value) Index(i int) *Value {
	if v == nil {
		return errValue(fmt.Errorf("%w: %d", ErrIndexOutOfRange, i))
	}
	if v.err != nil {
		return errValue(v.err)
	}
	s, ok := v.val.([]interface{})
	if !ok {
		return errValue(fmt.Errorf("%w: expected slice, got %T", ErrTypeMismatch, v.val))
	}
	if i < 0 || i >= len(s) {
		return errValue(fmt.Errorf("%w: %d", ErrIndexOutOfRange, i))
	}
	return newValue(s[i])
}

// Path resolves a dot-separated path against the value. Segments descend
// through maps by key and through slices by numeric index:
//
//	user.roles.0        // data["user"]["roles"][0]
//
// It records ErrNotFound, ErrIndexOutOfRange, or ErrTypeMismatch on failure.
func (v *Value) Path(path string) *Value {
	if v == nil {
		return errValue(fmt.Errorf("%w: %q", ErrNotFound, path))
	}
	cur := v
	for _, part := range splitPath(path) {
		if cur.err != nil {
			return cur
		}
		if _, ok := cur.val.([]interface{}); ok {
			i, err := strconv.Atoi(part)
			if err != nil {
				return errValue(fmt.Errorf("%w: expected slice index, got %q", ErrTypeMismatch, part))
			}
			cur = cur.Index(i)
			continue
		}
		cur = cur.Get(part)
	}
	return cur
}

// Map returns the receiver as a *Map. It records ErrTypeMismatch when the
// value is not a map.
func (v *Value) Map() *Map {
	if v == nil {
		return &Map{err: fmt.Errorf("%w: expected map, got <nil>", ErrTypeMismatch)}
	}
	if v.err != nil {
		return &Map{err: v.err}
	}
	m, ok := v.val.(map[string]interface{})
	if !ok {
		return &Map{err: fmt.Errorf("%w: expected map, got %T", ErrTypeMismatch, v.val)}
	}
	return &Map{data: m}
}

// Slice returns the receiver as a *Slice. It records ErrTypeMismatch when
// the value is not a slice.
func (v *Value) Slice() *Slice {
	if v == nil {
		return &Slice{err: fmt.Errorf("%w: expected slice, got <nil>", ErrTypeMismatch)}
	}
	if v.err != nil {
		return &Slice{err: v.err}
	}
	s, ok := v.val.([]interface{})
	if !ok {
		return &Slice{err: fmt.Errorf("%w: expected slice, got %T", ErrTypeMismatch, v.val)}
	}
	return &Slice{data: s}
}

func toInt64(val interface{}) (int64, bool) {
	switch x := val.(type) {
	case int:
		return int64(x), true
	case int8:
		return int64(x), true
	case int16:
		return int64(x), true
	case int32:
		return int64(x), true
	case int64:
		return x, true
	case uint:
		if uint64(x) > math.MaxInt64 {
			return 0, false
		}
		return int64(x), true
	case uint8:
		return int64(x), true
	case uint16:
		return int64(x), true
	case uint32:
		return int64(x), true
	case uint64:
		if x > math.MaxInt64 {
			return 0, false
		}
		return int64(x), true
	case float32:
		return floatToInt64(float64(x))
	case float64:
		return floatToInt64(x)
	case json.Number:
		n, err := x.Int64()
		return n, err == nil
	case string:
		n, err := strconv.ParseInt(strings.TrimSpace(x), 10, 64)
		return n, err == nil
	default:
		return 0, false
	}
}

func floatToInt64(f float64) (int64, bool) {
	if math.IsNaN(f) || math.IsInf(f, 0) || f != math.Trunc(f) {
		return 0, false
	}
	if f > math.MaxInt64 || f < math.MinInt64 {
		return 0, false
	}
	return int64(f), true
}

func toFloat64(val interface{}) (float64, bool) {
	switch x := val.(type) {
	case int:
		return float64(x), true
	case int8:
		return float64(x), true
	case int16:
		return float64(x), true
	case int32:
		return float64(x), true
	case int64:
		return float64(x), true
	case uint:
		return float64(x), true
	case uint8:
		return float64(x), true
	case uint16:
		return float64(x), true
	case uint32:
		return float64(x), true
	case uint64:
		return float64(x), true
	case float32:
		return float64(x), true
	case float64:
		return x, true
	case json.Number:
		f, err := x.Float64()
		return f, err == nil
	case string:
		f, err := strconv.ParseFloat(strings.TrimSpace(x), 64)
		return f, err == nil
	default:
		return 0, false
	}
}

func toBool(val interface{}) (bool, bool) {
	switch x := val.(type) {
	case bool:
		return x, true
	case string:
		b, err := strconv.ParseBool(strings.TrimSpace(x))
		return b, err == nil
	default:
		return false, false
	}
}

func unwrap(value interface{}) interface{} {
	switch x := value.(type) {
	case nil:
		return nil
	case *Map:
		if x == nil {
			return nil
		}
		return x.data
	case *Slice:
		if x == nil {
			return nil
		}
		return x.data
	case *Value:
		if x == nil {
			return nil
		}
		return x.val
	default:
		return value
	}
}

func deepCopy(value interface{}) interface{} {
	switch x := value.(type) {
	case map[string]interface{}:
		out := make(map[string]interface{}, len(x))
		for k, v := range x {
			out[k] = deepCopy(v)
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(x))
		for i, v := range x {
			out[i] = deepCopy(v)
		}
		return out
	default:
		return value
	}
}

package chainmap

import "fmt"

// Slice is a fluent wrapper around a []interface{}. Like Map and Value it
// records the first error encountered and exposes it through Err.
type Slice struct {
	data []interface{}
	err  error
}

// NewSlice returns a Slice wrapping data. A nil slice is replaced with an
// empty slice. The slice is used directly, not copied.
func NewSlice(data []interface{}) *Slice {
	if data == nil {
		data = make([]interface{}, 0)
	}
	return &Slice{data: data}
}

// Raw returns the underlying slice. Mutating it mutates the Slice.
func (s *Slice) Raw() []interface{} {
	if s == nil {
		return nil
	}
	return s.data
}

// Err returns the first error recorded during the chain, if any.
func (s *Slice) Err() error {
	if s == nil {
		return nil
	}
	return s.err
}

// Len returns the number of elements.
func (s *Slice) Len() int {
	if s == nil || s.data == nil {
		return 0
	}
	return len(s.data)
}

// Index returns the element at i, recording ErrIndexOutOfRange when i is
// invalid.
func (s *Slice) Index(i int) *Value {
	if s == nil {
		return errValue(fmt.Errorf("%w: %d", ErrIndexOutOfRange, i))
	}
	if s.err != nil {
		return errValue(s.err)
	}
	if i < 0 || i >= len(s.data) {
		return errValue(fmt.Errorf("%w: %d", ErrIndexOutOfRange, i))
	}
	return newValue(s.data[i])
}

// Values returns every element as a *Value.
func (s *Slice) Values() []*Value {
	if s == nil || s.data == nil {
		return nil
	}
	out := make([]*Value, 0, len(s.data))
	for _, v := range s.data {
		out = append(out, newValue(v))
	}
	return out
}

// Each calls fn for every element in order. Returning false stops the
// iteration early. It returns the receiver for chaining.
func (s *Slice) Each(fn func(i int, v *Value) bool) *Slice {
	if s == nil || s.err != nil {
		return s
	}
	for i, v := range s.data {
		if !fn(i, newValue(v)) {
			break
		}
	}
	return s
}

// Append adds values to the end of the slice and returns the receiver for
// chaining. Passing a *Map, *Slice, or *Value appends its underlying data.
func (s *Slice) Append(values ...interface{}) *Slice {
	if s == nil || s.err != nil {
		return s
	}
	for _, v := range values {
		s.data = append(s.data, unwrap(v))
	}
	return s
}

// Prepend inserts values at the front of the slice, preserving their order,
// and returns the receiver for chaining.
func (s *Slice) Prepend(values ...interface{}) *Slice {
	if s == nil || s.err != nil || len(values) == 0 {
		return s
	}
	prefix := make([]interface{}, 0, len(values)+len(s.data))
	for _, v := range values {
		prefix = append(prefix, unwrap(v))
	}
	s.data = append(prefix, s.data...)
	return s
}

// Transform replaces every element with the result of fn, returning the
// receiver for chaining.
func (s *Slice) Transform(fn func(i int, v *Value) interface{}) *Slice {
	if s == nil || s.err != nil {
		return s
	}
	for i, v := range s.data {
		s.data[i] = unwrap(fn(i, newValue(v)))
	}
	return s
}

// Filter returns a new Slice containing only the elements for which fn
// reports true. The receiver is left unchanged.
func (s *Slice) Filter(fn func(i int, v *Value) bool) *Slice {
	out := NewSlice(nil)
	if s == nil || s.err != nil {
		return out
	}
	for i, v := range s.data {
		if fn(i, newValue(v)) {
			out.data = append(out.data, v)
		}
	}
	return out
}

package chainmap

import (
	"errors"
	"testing"
)

func sample() *Map {
	return New(map[string]interface{}{
		"name": "ada",
		"age":  float64(36),
		"admin": true,
		"tags":  []interface{}{"go", "math"},
		"user": map[string]interface{}{
			"profile": map[string]interface{}{
				"city": "london",
			},
		},
	})
}

func TestGetAndCoercion(t *testing.T) {
	m := sample()

	if got := m.Get("name").String(); got != "ada" {
		t.Fatalf("String() = %q, want ada", got)
	}
	if got := m.Get("age").Int(); got != 36 {
		t.Fatalf("Int() = %d, want 36", got)
	}
	if got := m.Get("age").Float64(); got != 36 {
		t.Fatalf("Float64() = %v, want 36", got)
	}
	if got := m.Get("admin").Bool(); got != true {
		t.Fatalf("Bool() = %v, want true", got)
	}
	if err := m.Err(); err != nil {
		t.Fatalf("unexpected chain error: %v", err)
	}
}

func TestMissingKeyRecordsNotFound(t *testing.T) {
	m := sample()
	v := m.Get("missing")
	if !errors.Is(v.Err(), ErrNotFound) {
		t.Fatalf("Err() = %v, want ErrNotFound", v.Err())
	}
	if v.Exists() {
		t.Fatal("Exists() = true, want false")
	}
}

func TestTypeMismatchRecordsError(t *testing.T) {
	m := sample()
	if got := m.Get("name").Int(); got != 0 {
		t.Fatalf("Int() = %d, want 0", got)
	}
	if !errors.Is(m.Get("name").Err(), ErrTypeMismatch) {
		t.Fatalf("Err() = %v, want ErrTypeMismatch", m.Get("name").Err())
	}
}

func TestOrVariantsDoNotError(t *testing.T) {
	m := sample()
	if got := m.Get("missing").StringOr("fallback"); got != "fallback" {
		t.Fatalf("StringOr = %q, want fallback", got)
	}
	if got := m.Get("name").IntOr(7); got != 7 {
		t.Fatalf("IntOr = %d, want 7", got)
	}
	if got := m.Get("age").Int64Or(-1); got != 36 {
		t.Fatalf("Int64Or = %d, want 36", got)
	}
	if got := m.Get("name").BoolOr(true); got != true {
		t.Fatalf("BoolOr = %v, want true", got)
	}
	if got := m.Get("missing").Float64Or(1.5); got != 1.5 {
		t.Fatalf("Float64Or = %v, want 1.5", got)
	}
}

func TestPathTraversal(t *testing.T) {
	m := sample()
	if got := m.Path("user.profile.city").String(); got != "london" {
		t.Fatalf("Path = %q, want london", got)
	}
	if got := m.Path("tags.1").String(); got != "math" {
		t.Fatalf("Path = %q, want math", got)
	}
	if !errors.Is(m.Path("tags.9").Err(), ErrIndexOutOfRange) {
		t.Fatalf("Err() = %v, want ErrIndexOutOfRange", m.Path("tags.9").Err())
	}
	if !errors.Is(m.Path("user.nope.city").Err(), ErrNotFound) {
		t.Fatalf("Err() = %v, want ErrNotFound", m.Path("user.nope.city").Err())
	}
}

func TestSetAndDelete(t *testing.T) {
	m := sample()
	m.Set("name", "grace").Set("active", true).Delete("age")

	if m.Get("name").String() != "grace" {
		t.Fatal("Set did not update name")
	}
	if !m.Get("active").Bool() {
		t.Fatal("Set did not add active")
	}
	if m.Has("age") {
		t.Fatal("Delete did not remove age")
	}
}

func TestSetPathCreatesIntermediateMaps(t *testing.T) {
	m := New(nil)
	m.SetPath("a.b.c", 42)
	if got := m.Path("a.b.c").Int(); got != 42 {
		t.Fatalf("SetPath value = %d, want 42", got)
	}

	bad := New(map[string]interface{}{"a": "not-a-map"})
	bad.SetPath("a.b", 1)
	if !errors.Is(bad.Err(), ErrTypeMismatch) {
		t.Fatalf("Err() = %v, want ErrTypeMismatch", bad.Err())
	}
}

func TestDeletePath(t *testing.T) {
	m := sample()
	m.DeletePath("user.profile.city")
	if m.Path("user.profile.city").Err() == nil {
		t.Fatal("DeletePath did not remove value")
	}
}

func TestSliceOperations(t *testing.T) {
	s := NewSlice([]interface{}{1, 2, 3})
	s.Append(4).Prepend(0)

	want := []int{0, 1, 2, 3, 4}
	got := s.Values()
	if len(got) != len(want) {
		t.Fatalf("len = %d, want %d", len(got), len(want))
	}
	for i, w := range want {
		if v := got[i].Int(); v != w {
			t.Fatalf("index %d = %d, want %d", i, v, w)
		}
	}

	doubled := NewSlice([]interface{}{1, 2, 3}).Transform(func(_ int, v *Value) interface{} {
		return v.Int() * 2
	})
	if doubled.Index(2).Int() != 6 {
		t.Fatalf("Transform = %d, want 6", doubled.Index(2).Int())
	}

	evens := NewSlice([]interface{}{1, 2, 3, 4}).Filter(func(_ int, v *Value) bool {
		return v.Int()%2 == 0
	})
	if evens.Len() != 2 || evens.Index(0).Int() != 2 || evens.Index(1).Int() != 4 {
		t.Fatalf("Filter produced %v", evens.Raw())
	}
}

func TestValueSliceAndMap(t *testing.T) {
	m := sample()
	tags := m.Get("tags").Slice()
	if tags.Len() != 2 {
		t.Fatalf("tags len = %d, want 2", tags.Len())
	}
	if tags.Index(0).String() != "go" {
		t.Fatalf("tags[0] = %q, want go", tags.Index(0).String())
	}

	if _, ok := m.Get("user").Map().Get("profile").Map().Raw()["city"]; !ok {
		t.Fatal("nested Map access failed")
	}
}

func TestEachAndTransform(t *testing.T) {
	sum := 0
	New(map[string]interface{}{"a": 1, "b": 2, "c": 3}).
		Each(func(_ string, v *Value) bool { sum += v.Int(); return true })
	if sum != 6 {
		t.Fatalf("Each sum = %d, want 6", sum)
	}

	m := New(map[string]interface{}{"a": 1, "b": 2})
	m.Transform(func(_ string, v *Value) interface{} { return v.Int() * 10 })
	if m.Get("a").Int() != 10 || m.Get("b").Int() != 20 {
		t.Fatalf("Transform result = %v", m.Raw())
	}
}

func TestMergeAndClone(t *testing.T) {
	base := New(map[string]interface{}{"a": 1, "nested": map[string]interface{}{"x": 1}})
	base.Merge(New(map[string]interface{}{"b": 2}))
	if base.Len() != 3 {
		t.Fatalf("Len = %d, want 3", base.Len())
	}

	clone := base.Clone()
	clone.SetPath("nested.x", 99)
	if base.Path("nested.x").Int() != 1 {
		t.Fatal("Clone shares nested maps with the original")
	}
}

func TestParseJSON(t *testing.T) {
	m, err := ParseJSON([]byte(`{"user":{"name":"ada","age":36},"tags":["a","b"]}`))
	if err != nil {
		t.Fatalf("ParseJSON: %v", err)
	}
	if m.Path("user.name").String() != "ada" {
		t.Fatalf("name = %q, want ada", m.Path("user.name").String())
	}
	if m.Path("user.age").Int() != 36 {
		t.Fatalf("age = %d, want 36", m.Path("user.age").Int())
	}
	if m.Path("tags.1").String() != "b" {
		t.Fatalf("tags[1] = %q, want b", m.Path("tags.1").String())
	}
}

func TestErrorPropagationThroughChain(t *testing.T) {
	m := sample()
	v := m.Path("user.missing.city")
	if !errors.Is(v.Err(), ErrNotFound) {
		t.Fatalf("Err() = %v, want ErrNotFound", v.Err())
	}
	// Subsequent reads after an error stay in the error state.
	if v.Get("anything").Err() == nil {
		t.Fatal("error was not propagated")
	}
}

